import{_ as o,o as a,c as t,a2 as r}from"./chunks/framework.DCVnL8g5.js";const h=JSON.parse('{"title":"Patrones de arquitectura","description":"","frontmatter":{},"headers":[],"relativePath":"full-stack/frontend/zustand/07-patrones-de-arquitectura.md","filePath":"full-stack/frontend/zustand/07-patrones-de-arquitectura.md","lastUpdated":1789040978000,"isDraft":false}'),s={name:"full-stack/frontend/zustand/07-patrones-de-arquitectura.md"};function n(c,e,i,d,l,u){return a(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="patrones-de-arquitectura" tabindex="-1">Patrones de arquitectura <a class="header-anchor" href="#patrones-de-arquitectura" aria-label="Permalink to &quot;Patrones de arquitectura&quot;">​</a></h1><p>Zustand crece <strong>con el problema</strong>. Un store de cinco campos no necesita <code>actions/</code>, <code>reducers/</code>, <code>effects/</code> ni un bus de eventos.</p><p>Documentación: <a href="https://zustand.docs.pmnd.rs/learn/guides/slices-pattern" target="_blank" rel="noreferrer">slices</a>, <a href="https://zustand.docs.pmnd.rs/learn/guides/flux-inspired-practice" target="_blank" rel="noreferrer">Flux inspired</a>, <a href="https://zustand.docs.pmnd.rs/learn/guides/beginner-typescript" target="_blank" rel="noreferrer">varios stores (TS)</a>.</p><h2 id="tres-tamanos" tabindex="-1">Tres tamaños <a class="header-anchor" href="#tres-tamanos" aria-label="Permalink to &quot;Tres tamaños&quot;">​</a></h2><p><strong>Archivo único</strong> — <code>carritoStore.js</code> con state + acciones. El 80 % de los casos.</p><p><strong>Feature store</strong> — <code>features/carrito/carrito.store.ts</code> junto a la UI del carrito. Otro fichero <code>features/prefs/prefs.store.ts</code> para tema/filtros. Varios stores <strong>independientes</strong> cuando los dominios no se pisan.</p><p><strong>Slices</strong> — un store grande partido en funciones <code>createXSlice(set, get)</code> y un <code>create((...a) =&gt; ({ ...createCarritoSlice(...a), ...createPrefsSlice(...a) }))</code>. Middleware (<code>persist</code>, <code>devtools</code>) <strong>solo</strong> en el store combinado.</p><p>La guía Flux sugiere <strong>un</strong> store global y slices si crece. Zustand también permite varios stores (la propia doc TS). Elige: un bound store <em>o</em> stores separados. <strong>No</strong> una red que se importa en círculo (<code>carrito</code> llama <code>prefs</code> que llama <code>carrito</code>).</p><h2 id="no-al-mega-useappstore" tabindex="-1">No al mega-<code>useAppStore</code> <a class="header-anchor" href="#no-al-mega-useappstore" aria-label="Permalink to &quot;No al mega-`useAppStore`&quot;">​</a></h2><p>Meter auth, modal, carrito, toasts, productos, caché HTTP y formularios en un objeto “porque Flux dice un store” sin slices es un cajón. Si está junto, <strong>parte</strong>. Si no se tocan, <strong>dos módulos</strong>.</p><h2 id="acciones-de-dominio" tabindex="-1">Acciones de dominio <a class="header-anchor" href="#acciones-de-dominio" aria-label="Permalink to &quot;Acciones de dominio&quot;">​</a></h2><p>Junto al estado, sí. Setters <code>setNombre</code> / <code>setEmail</code> / <code>setEdad</code> por campo suelen ser ruido. Prefiere <code>actualizarPerfil({ nombre, email })</code>, <code>checkout()</code>, <code>resetFiltros()</code>, <code>anadir(id)</code>.</p><p>Siempre actualiza con <code>set</code> / <code>setState</code> (Flux). Puedes poner alguna acción <strong>fuera</strong> del store (<code>useCarritoStore.setState</code>) si hace falta; no es la primera opción.</p><p>No reconstruyas <code>dispatch</code> + <code>switch</code> salvo que el equipo ya viva en Redux. Existe <code>redux</code> middleware; este manual no lo recomienda como camino Zustand.</p><h2 id="coordinar-stores" tabindex="-1">Coordinar stores <a class="header-anchor" href="#coordinar-stores" aria-label="Permalink to &quot;Coordinar stores&quot;">​</a></h2><p>Una acción rara puede leer <code>usePrefsStore.getState()</code> <strong>desde</strong> el carrito. Si eso se vuelve habitual, o unes en slices o tienes un olor. No diseñes un event bus “porque desacopla”.</p><h2 id="zustand-frente-a-redux-toolkit" tabindex="-1">Zustand frente a Redux Toolkit <a class="header-anchor" href="#zustand-frente-a-redux-toolkit" aria-label="Permalink to &quot;Zustand frente a Redux Toolkit&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>Zustand</th><th>RTK</th></tr></thead><tbody><tr><td>Tamaño mental</td><td>Store + <code>set</code> + selector</td><td>Slice, actions, store, a menudo Query</td></tr><tr><td>Stores</td><td>Uno o varios, o slices</td><td>Un store, varios slices</td></tr><tr><td>Server cache</td><td>No es el trabajo</td><td>RTK Query</td></tr><tr><td>Tooling</td><td>DevTools opcional</td><td>Convención + ecosistema</td></tr><tr><td>Provider</td><td>Opcional (sí en SSR/instancia)</td><td><code>Provider</code> habitual</td></tr></tbody></table><p>Complementarios, no “el mismo producto con menos npm”. Tras el manual Redux: Zustand no es RTK Query más simple.</p><h2 id="errores-habituales" tabindex="-1">Errores habituales <a class="header-anchor" href="#errores-habituales" aria-label="Permalink to &quot;Errores habituales&quot;">​</a></h2><ul><li>Slices <em>y</em> seis stores que se llaman entre sí.</li><li>Acciones vacías que solo hacen <code>set({ x })</code> con otro nombre.</li><li>Copiar la carpeta <code>features/</code> de un tutorial Redux al milímetro.</li></ul><h2 id="buenas-practicas" tabindex="-1">Buenas prácticas <a class="header-anchor" href="#buenas-practicas" aria-label="Permalink to &quot;Buenas prácticas&quot;">​</a></h2><ul><li>Empieza en un fichero; extrae feature o slice cuando el scroll duela.</li><li>Acciones que nombran <strong>qué hizo el usuario</strong>.</li><li>Client state aquí; server state fuera.</li></ul><h2 id="ejercicio" tabindex="-1">Ejercicio <a class="header-anchor" href="#ejercicio" aria-label="Permalink to &quot;Ejercicio&quot;">​</a></h2><ol><li>Parte <code>prefs</code> a otro store y deja el carrito solo.</li><li>Escribe un <code>createCarritoSlice</code> y combínalo.</li><li>Busca un <code>setFoo</code> y renómbralo a una intención (<code>aplicarCupon</code>).</li></ol><h2 id="siguiente-paso" tabindex="-1">Siguiente paso <a class="header-anchor" href="#siguiente-paso" aria-label="Permalink to &quot;Siguiente paso&quot;">​</a></h2><p>Continúa con <a href="./08-testing">Testing</a>.</p>',27)])])}const m=o(s,[["render",n]]);export{h as __pageData,m as default};
